use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin") ?? ""
    let mut k = 0
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut cur = ""
    let mut in_head = true
    for c in text.chars() {
        if in_head {
            if c == '\n' {
                in_head = false
            } else if c >= '0' && c <= '9' {
                k = k * 10 + (c as int - '0' as int)
            }
            continue
        }
        if c.is_ascii_alphanumeric() {
            cur = cur + c.to_ascii_lowercase().to_string()
        } else if cur.len() > 0 {
            counts.entry(cur).and_modify(|v| *v += 1).or_insert(1)
            cur = ""
        }
    }
    if cur.len() > 0 {
        counts.entry(cur).and_modify(|v| *v += 1).or_insert(1)
    }
    let mut items: Vec<(string, int)> = []
    for key in counts.keys() {
        items.push((key, counts.get(key) ?? 0))
    }
    items.sort_by_key(|p| p.0.clone())
    items.sort_by_key(|p| 0 - p.1)
    let mut i = 0
    for it in items {
        if i >= k { break }
        println("${it.0} ${it.1}")
        i += 1
    }
}

